def amicable_numbers_sum(n):
    def sum_of_divisors(num):
        total = 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:
                    total += num // i
        return total

    def is_amicable(x):
        y = sum_of_divisors(x)
        return x != y and sum_of_divisors(y) == x

    return sum(x for x in range(2, n+1) if is_amicable(x))
```

