def get_noOfways(n: int) -> int:
    """Return the number of ways to tile a 1×n board with 1×2 dominoes."""
    if n <= 0:
        return 0
    a, b = 1, 1  # ways for n=1 and n=2
    if n == 1:
        return a
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b
```

