def find_exponentio(a, b):
    """
    Return a tuple where each element is the corresponding element of `a`
    raised to the power of the element in `b`.
    """
    if len(a) != len(b):
        raise ValueError("Tuples must have the same length.")
    return tuple(pow(x, y) for x, y in zip(a, b))
