def max_sub_array_sum(arr, n):
    max_sum = cur_sum = arr[0]
    max_len = cur_len = 1

    for i in range(1, n):
        if cur_sum + arr[i] > arr[i]:
            cur_sum += arr[i]
            cur_len += 1
        else:
            cur_sum = arr[i]
            cur_len = 1

        if cur_sum > max_sum:
