def sum_Of_product(n):
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        prod = 1
        for i in range(2, num + 1):
            prod *= i
        return prod

    def binomial_coefficient(n, k):
        return factorial(n) // (factorial(k) * factorial(n - k))

    sum_of_products = 0
    for k in range(n + 1):
        for j in range(n + 1):
            sum_of_products += binomial_coefficient(n, k) * binomial_coefficient(n, j)
    return sum_of_products
```

