def tuple_to_float(t: tuple[int, int]) -> float:
    """
    Convert a tuple of two integers (whole_part, fractional_part) into a floating-point number.
    Example: (4, 56) -> 4.56
    """
    if not isinstance(t, tuple) or len(t) != 2:
        raise ValueError("Input must be a tuple of two integers.")
    whole, frac = t
    if not (isinstance(whole, int) and isinstance(frac, int)):
        raise TypeError("Both elements of the tuple must be integers.")
    return float(f"{whole}.{frac}")
```

