def min_cost(cost, m, n):
    def min_cost_util(cost, m, n, dp):
        if m < 0 or n < 0:
            return float('inf')
        elif m == 0 and n == 0:
            return cost[m][n]
        if dp[m][n] != -1:
            return dp[m][n]
        dp[m][n] = cost[m][n] + min(
            min_cost_util(cost, m-1, n-1, dp),
            min_cost_util(cost, m-1, n, dp),
            min_cost_util(cost, m, n-1, dp)
        )
        return dp[m][n]

    dp = [[-1 for _ in range(n+1)] for _ in range(m+1)]
    return min_cost_util(cost, m, n, dp)
```

