    def binomial_coefficient(n, k):
        if k == 0 or k == n:
            return 1
        if k > n:
            return 0
        num = 1
        den = 1
        for i in range(min(k, n - k)):
            num *= n - i
            den *= i + 1
        return num // den

    return sum(binomial_coefficient(n, k) ** 2 for k in range(n + 1))
