def compute_Last_Digit(a, b):
    def factorial(n):
        if n == 0 or n == 1:
            return 1
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result

    def last_digit_of_division(a, b):
        if b < a:
            return -1
        fact_a = factorial(a)
        fact_b = factorial(b)
        division_result = fact_b // fact_a
        return division_result % 10

    return last_digit_of_division(a, b)
